import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"功能详解","description":"","frontmatter":{},"headers":[],"relativePath":"guide/features.md","filePath":"guide/features.md","lastUpdated":1785861127000}'),r={name:"guide/features.md"};function i(s,e,l,c,n,h){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="功能详解" tabindex="-1">功能详解 <a class="header-anchor" href="#功能详解" aria-label="Permalink to &quot;功能详解&quot;">​</a></h1><p>CZero 的每项功能都可在 <code>config.json</code> 中单独开关，并按各自的计划自动触发。本页说明每个功能<strong>做什么、什么时候做、有哪些保护</strong>。逐字段的取值见<a href="/guide/configuration">配置参考</a>。</p><h2 id="缓存清理" tabindex="-1">缓存清理 <a class="header-anchor" href="#缓存清理" aria-label="Permalink to &quot;缓存清理&quot;">​</a></h2><p>为高频应用（微信、QQ、抖音）提供各自独立的清理器，按 <code>app_clean.detect_schedule</code> 的频率触发。</p><h3 id="触发前的检测" tabindex="-1">触发前的检测 <a class="header-anchor" href="#触发前的检测" aria-label="Permalink to &quot;触发前的检测&quot;">​</a></h3><p>每次触发前会先看应用当前的状态，避免无谓或有害的清理：</p><ul><li><strong>前台应用不清理</strong> —— 应用正处于前台使用时，本轮跳过，避免影响正在进行的操作。</li><li><strong>游戏前台保护</strong> —— 前台为游戏时不执行清理。</li></ul><h3 id="每个应用的开关" tabindex="-1">每个应用的开关 <a class="header-anchor" href="#每个应用的开关" aria-label="Permalink to &quot;每个应用的开关&quot;">​</a></h3><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;wechat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;enabled&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;enhanced&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><ul><li><code>enabled</code> —— 是否清理该应用。</li><li><code>enhanced</code> —— <strong>增强模式</strong>。开启后清理范围更广，默认关闭以求稳妥。</li></ul><h3 id="其他应用清理" tabindex="-1">其他应用清理 <a class="header-anchor" href="#其他应用清理" aria-label="Permalink to &quot;其他应用清理&quot;">​</a></h3><p><code>app_clean.other</code> 处理三大应用之外的缓存，按其 <code>schedule</code> 定时执行（默认每天 03:00）。</p><h3 id="总开关与时序屏障" tabindex="-1">总开关与时序屏障 <a class="header-anchor" href="#总开关与时序屏障" aria-label="Permalink to &quot;总开关与时序屏障&quot;">​</a></h3><ul><li>受总开关 <code>general.auto_clean</code> 控制。</li><li>受 <code>general.temporal_barrier_days</code>（<strong>时序屏障</strong>）保护：只清理 N 天以前的文件，保护近期数据；设为 <code>0</code> 表示不启用。</li></ul><h2 id="后台压制" tabindex="-1">后台压制 <a class="header-anchor" href="#后台压制" aria-label="Permalink to &quot;后台压制&quot;">​</a></h2><p>按 <code>suppress.detect_schedule</code> 的频率，周期性结束目标应用在后台的进程，释放内存、减少后台耗电。</p><ul><li><strong>只动子进程</strong> —— 主进程不受影响，通知与消息推送照常。</li><li><strong>前台应用绝不动</strong> —— 正在前台的应用不会被压制；本轮识别不出前台应用时也会跳过，避免误伤。</li><li><strong>名单可改</strong> —— 默认针对 微信 / QQ / 支付宝，可在 CZeroX 里增删应用、按应用单独启停。</li></ul><h2 id="f2fs-垃圾回收" tabindex="-1">F2FS 垃圾回收 <a class="header-anchor" href="#f2fs-垃圾回收" aria-label="Permalink to &quot;F2FS 垃圾回收&quot;">​</a></h2><p>在存储空闲吃紧时触发 F2FS 垃圾回收（GC），把碎片化的空间整理出来。</p><p>GC 是磁盘密集操作，所以只在设备真正空闲时才动手。以下任一条不满足都会跳过本轮：</p><table tabindex="0"><thead><tr><th>条件</th><th>字段</th><th>默认</th></tr></thead><tbody><tr><td>存储确实需要回收</td><td><code>free_percent</code> / <code>target_percent</code></td><td>空闲比例低于 95% 才触发，回到 98% 即完成</td></tr><tr><td>屏幕必须是熄灭的</td><td><code>wait_screen_off_timeout</code></td><td>最多等 30 秒，到点仍亮屏就放弃</td></tr><tr><td>距上次回收的间隔</td><td><code>min_interval_hours</code></td><td>6 小时</td></tr><tr><td>必须在充电</td><td><code>require_charging</code></td><td>关（不要求）</td></tr><tr><td>非充电时的最低电量</td><td><code>min_battery</code></td><td>40%</td></tr><tr><td>电池温度上限</td><td><code>max_battery_temp</code></td><td>40.0°C</td></tr></tbody></table><p>另有 <code>max_runtime_sec</code> 限制单次最长运行时长，到时强制停止。</p><div class="tip custom-block"><p class="custom-block-title">长期观察不到执行属于正常</p><p>准入条件较为严格，且系统自身正在执行维护时 CZero 会主动让路。若连续数次回收收效甚微，间隔还会自动拉长，避免无谓的重复尝试。</p></div><blockquote><p>GC 功能需要 <code>/data</code> 为 F2FS 分区。非 F2FS 设备可将 <code>gc.enabled</code> 设为 <code>false</code>，其余功能不受影响。</p></blockquote><h2 id="fstrim" tabindex="-1">fstrim <a class="header-anchor" href="#fstrim" aria-label="Permalink to &quot;fstrim&quot;">​</a></h2><p><code>trim</code> 是独立于 GC 的一项任务（默认每 7 天 04:00 一次），把已释放的空间告知底层存储，让 UFS / eMMC 自己的垃圾回收有据可依，长期有助于维持写入性能。</p><ul><li>调度与 GC <strong>完全独立</strong>，也不受 <code>gc.enabled</code> 影响。</li><li>同样要求息屏；屏幕亮着则本轮跳过。</li></ul><div class="warning custom-block"><p class="custom-block-title">别把周期调得太密</p><p>fstrim 对存储器件有实际写入压力，默认的每周一次已经足够，不建议改成每天。</p></div><h2 id="精细化压制" tabindex="-1">精细化压制 <a class="header-anchor" href="#精细化压制" aria-label="Permalink to &quot;精细化压制&quot;">​</a></h2><p>上面的<a href="#后台压制">后台压制</a>是直接把后台进程结束掉；<strong>精细化压制</strong>是它的温和版本 —— <strong>压制而不杀死</strong>：应用被挂起后不再消耗 CPU，但内存里的状态完整保留，切回去瞬间就恢复，不用重新加载。</p><p>这套能力由 Android 系统本身提供，模块不代劳执行，只负责在开机时把它调到可用状态：</p><table tabindex="0"><thead><tr><th>字段</th><th>做什么</th></tr></thead><tbody><tr><td><code>auto_enable</code></td><td>每次开机打开系统的精细化压制能力</td></tr><tr><td><code>disable_vendor_guard</code></td><td>关掉厂商自研的保活/压制，避免两套策略互相打架</td></tr></tbody></table><p>参与压制的应用名单在 CZeroX 里管理，不写进 <code>config.json</code>。</p><div class="tip custom-block"><p class="custom-block-title">两者如何选择</p><p>可以并存。后台压制适用于结束后无副作用、常驻仅占内存的子进程；精细化压制适用于希望保留运行现场、但不允许其在后台活动的应用。</p></div><div class="warning custom-block"><p class="custom-block-title">需要 Android 12+</p><p>更低版本上这两个开关不会生效。</p></div><h2 id="空文件夹清理" tabindex="-1">空文件夹清理 <a class="header-anchor" href="#空文件夹清理" aria-label="Permalink to &quot;空文件夹清理&quot;">​</a></h2><p>按 <code>empty_folder.schedule</code> 定时清扫残留的空目录（默认每天 04:00）。清扫范围与白名单都可以在 CZeroX 里编辑，规则按分组组织，可整组启停。</p><h2 id="自定义路径清理" tabindex="-1">自定义路径清理 <a class="header-anchor" href="#自定义路径清理" aria-label="Permalink to &quot;自定义路径清理&quot;">​</a></h2><p>除内置规则外，你可以声明自己的清理路径，由每日任务统一清扫，同时用白名单保护不想被碰的目录。两者都在 CZeroX 的规则编辑器里管理，重装模块时会被继承。</p><p>规则支持通配符，也会自动去重（父目录已在列表里时，其下的子路径不重复处理），白名单的优先级始终更高。</p><p>除了按路径分组的规则，还有一份<strong>按应用组织</strong>的规则表：在 CZeroX 的「应用缓存」页里可以按应用查看各路径的实际占用、逐条增删，也可以从云端共享库拉取别人验证过的规则。两份规则在清理时合并处理，行为完全一致。</p><p>你也可以订阅第三方<a href="/guide/rule-source">规则源</a>，添加后每天自动更新一次。</p><p>清理并非直接删除，而是先移入回收站（见下节），默认保留 7 天，期间可完整恢复。</p><h2 id="回收站与恢复" tabindex="-1">回收站与恢复 <a class="header-anchor" href="#回收站与恢复" aria-label="Permalink to &quot;回收站与恢复&quot;">​</a></h2><p>为避免误删无法挽回，其他 / 自定义路径清理<strong>不做真正的删除</strong>，而是把命中的文件<strong>移动到回收站</strong>保存一段时间，确认无碍后才随过期自动清除。</p><ul><li><strong>移动而非删除</strong> —— 被清理的文件按原目录结构保存，可以<strong>原样恢复回原位</strong>，包括符号链接。</li><li><strong>按次归档</strong> —— 每次清理单独成一组记录，可以看到这次清了哪些文件、多大、什么时候过期。</li><li><strong>默认保留 7 天</strong> —— 可用 <code>general.recycle_keep_days</code> 调整（缺省或填 <code>0</code> 即 7 天）。过期后自动清除。</li><li><strong>不被相册扫描</strong> —— 移进去的图片 / 视频不会出现在媒体库里。</li><li><strong>保留修改时间</strong> —— 恢复后不会被时序屏障误判为&quot;新文件&quot;。</li><li><strong>回收站自我保护</strong> —— 清理规则即使匹配到内置存储根目录，也永远不会清理回收站自身。</li></ul><p>回收站位于内置存储的 <code>Recycle</code> 文件夹，日常通过 CZeroX 的回收站页面查看与恢复即可。</p><h2 id="统计与日志" tabindex="-1">统计与日志 <a class="header-anchor" href="#统计与日志" aria-label="Permalink to &quot;统计与日志&quot;">​</a></h2><ul><li><strong>统计</strong> —— 各应用的清理次数、压制次数与释放空间都会累计，并保留近 90 天的每日历史，CZeroX 的「清理趋势」页据此画柱状图。每天 00:00 结转当日计数，关机跨过 0 点也不会漏。</li><li><strong>日志</strong> —— 开启 <code>general.log</code> 后，所有组件写入同一份每日日志，每条带来源标签（<code>[定时]</code> <code>[检测]</code> <code>[微信]</code> <code>[压制]</code> <code>[GC]</code> <code>[空文件夹]</code> <code>[自定义]</code> 等），便于区分是哪个环节产生的。日志只保留当天。</li></ul><p>两者默认关闭，可随时开启或关闭。</p><h2 id="超级岛通知" tabindex="-1">超级岛通知 <a class="header-anchor" href="#超级岛通知" aria-label="Permalink to &quot;超级岛通知&quot;">​</a></h2><p>清理开始与结束时会通知 CZeroX，在应用侧显示执行进度 / 结果（含超级岛）。由 <code>general.notification</code> 控制。</p>',52)])])}const g=t(r,[["render",i]]);export{u as __pageData,g as default};
